import { useCategoricalBarChartBaseConfig } from './useCategoricalBarChartBaseConfig.js';
import { uuidv4 } from '../../../core/utils/uuidv4.js';
import { getColorPalette } from '../../core/functions/get-color-palette.js';
import { ColorToken } from '../../core/types/color-palette.js';
import { CategoricalChartData } from '../contexts/CategoricalBarChartDataContext.js';
import { isGrouped } from '../functions/layout.js';
import {
  WeakMapDimension,
  WeakMapCategory,
  DimensionMetadata,
  Dimension,
  CategoryMetadata,
  CategoricalBarData,
} from '../types/categorical-bar-chart-data.js';
import { CategoricalBarChartData } from '../types/categorical-bar-chart.js';

const getTotalValue = (categoryData: CategoricalBarChartData): number =>
  Object.values(categoryData.value).reduce(
    (total, dimensionValue) => total + Math.abs(dimensionValue),
    0,
  );

const getRelativeValue = (value: number, total: number): number =>
  (value * 100) / total;

const getValue = (value: unknown, relativeTotalValue?: number): number => {
  const numericValue = Number(value);
  const numberValue = isNaN(numericValue) ? 0 : numericValue;

  return relativeTotalValue
    ? getRelativeValue(numberValue, relativeTotalValue)
    : numberValue;
};

function createCategoryMetadata(id: string, name: string): CategoryMetadata {
  return { id, name };
}

/**
 * Generate bar data and weakmaps to be filled into categorical bar chart provider
 * - generate single or multiple dimensions object from consumer with ids
 * - generate colors by dimensions

 *
 * @param initialData - Categorical data from component
 * @returns Categorical chart data
 */
export function useGenerateCategoricalBarData(
  initialData: CategoricalBarChartData[],
): CategoricalChartData {
  const { valueRepresentation, colorPalette, colorPaletteMode, groupMode } =
    useCategoricalBarChartBaseConfig();

  const isRelative = valueRepresentation === 'relative';
  const firstCategoryUnit = initialData[0]?.unit;

  const uniqueDimensions = new Set<string>();
  const categoricalData: CategoricalBarData[] = [];
  const categoryMap: WeakMapCategory = new WeakMap();
  const dimensionMap: WeakMapDimension = new WeakMap();
  const colorByDimension: Map<string, ColorToken> = new Map();

  for (const categoryData of initialData) {
    const categoryId = uuidv4();
    const {
      unit,
      category: categoryName,
      value: categoryValue,
      color: categoryColor,
      ...rest
    } = categoryData;
    const newCategory: CategoricalBarData = {
      id: categoryId,
      name: categoryName,
      unit,
      dimensions: [],
      ...rest,
    };

    const isSingleDimension =
      unit !== firstCategoryUnit || typeof categoryValue !== 'object';
    const categoricalColorPalette =
      colorPaletteMode === 'multi-color' ||
      isGrouped(groupMode) ||
      !isSingleDimension;
    const relativeTotalValue = isRelative
      ? isSingleDimension
        ? Math.max(...initialData.map((d) => d.value as number))
        : getTotalValue(categoryData)
      : undefined;

    if (isSingleDimension) {
      const value = getValue(categoryValue, relativeTotalValue);
      const colorPositionIndex = initialData.indexOf(categoryData);
      const paletteColorPosition = categoricalColorPalette
        ? colorPositionIndex
        : 0;
      const dimensionName = categoryName;
      const id = uuidv4();
      const color = colorByDimension[dimensionName]
        ? colorByDimension[dimensionName]
        : categoryColor
        ? { Default: categoryColor }
        : getColorPalette(categoryName, paletteColorPosition, colorPalette);

      colorByDimension[dimensionName] = color;

      const newDimension: Dimension = {
        ...rest,
        id,
        name: dimensionName,
        value,
      };

      const dimensionMetadata: DimensionMetadata = {
        id,
        name: dimensionName,
        value,
        color,
      };

      uniqueDimensions.add(dimensionName);
      dimensionMap.set(newDimension, dimensionMetadata);
      newCategory.dimensions.push(newDimension);
    } else {
      Object.entries(categoryValue).forEach(
        ([dimensionKey, dimensionValue], index) => {
          const value = getValue(dimensionValue, relativeTotalValue);
          const paletteColorPosition = categoricalColorPalette ? index : 0;
          const color = colorByDimension[dimensionKey]
            ? colorByDimension[dimensionKey]
            : getColorPalette(dimensionKey, paletteColorPosition, colorPalette);

          colorByDimension[dimensionKey] = color;

          const id = uuidv4();
          const name = dimensionKey;

          const newDimension: Dimension = {
            ...rest,
            id,
            name,
            value,
          };

          const dimensionMetadata: DimensionMetadata = {
            id,
            name,
            value,
            color,
          };

          uniqueDimensions.add(dimensionKey);
          dimensionMap.set(newDimension, dimensionMetadata);
          newCategory.dimensions.push(newDimension);
        },
      );
    }

    const categoryMedatada = createCategoryMetadata(categoryId, categoryName);
    categoryMap.set(newCategory, categoryMedatada);
    categoricalData.push(newCategory);
  }

  return {
    categoryMap,
    dimensionMap,
    categoricalData,
    uniqueDimensions: Array.from(uniqueDimensions),
    unit: isRelative ? 'percent' : firstCategoryUnit,
  };
}
